<?php
function proxmox_service_type(array $service): string {return ($service['meta']['type']??'qemu')==='lxc'?'lxc':'qemu';}
function proxmox_marker_matches(array $config,string $expected): bool {
    // Proxmox appends a line ending when reading descriptions from its config file.
    return is_string($config['description']??null) && hash_equals($expected,rtrim($config['description'],"\r\n"));
}
function lxc_network_config(array $ip): string {
    if(!filter_var($ip['address'],FILTER_VALIDATE_IP,FILTER_FLAG_IPV4) || !filter_var($ip['gateway'],FILTER_VALIDATE_IP,FILTER_FLAG_IPV4) || !preg_match('/^[\w.-]+$/D',$ip['bridge']))throw new RuntimeException('Die reservierte Netzwerkkonfiguration ist ungültig.');
