    // as a root-only change, so omit disabled flags when creating from an OS image.
    // Backup restores keep explicit overrides so inherited features are not enabled silently.
    if(!str_contains($template['archive'],':backup/')){
        $features=[];foreach(['nesting','keyctl'] as $flag)if(!empty($s[$flag]))$features[]=$flag.'=1';
        if($features)$params['features']=implode(',',$features);else unset($params['features']);
    }
    if(str_contains($template['archive'],':backup/')){$params['restore']=1;$params['unique']=1;}if($reinstall){$params['restore']=1;$params['force']=1;unset($params['pool']);}return $params;
