function queue_server_credentials(array $service,string $key): void {
    $customer=one('SELECT email FROM customers WHERE id=?',[$service['customer_id']]);
    queue_shop_mail($key,$customer['email'],'Dein Server ist bereit','Die Zugangsdaten findest du nach Anmeldung im Kundenbereich: '.Config::FRONTPANEL_SITE_URL.'/konto/verwalten?id='.$service['id']);
}
