    $disk=$type==='lxc'?['disk_device'=>'rootfs','disk_target_gb'=>(int)($service['meta']['disk_base_gb']??json_decode($base['server_template']['settings']??'{}',true)['disk_gb']??0)+(int)($target['disk_extra_gb']??0)]:proxmox_disk_configuration($config,0);
    if($type==='qemu'){$current=proxmox_disk_configuration($config,1);$device=$current['disk_device'];$old=module_effective_profile($service);$baseline=(int)($service['meta']['disk_base_gb']??($current['disk_target_gb']-1-(int)($old['disk_extra_gb']??0)));$disk=['disk_device'=>$device,'disk_target_gb'=>$baseline+(int)($target['disk_extra_gb']??0)];$m=$service['meta'];$m['disk_base_gb']=$baseline;query('UPDATE shop_resource_links SET metadata=? WHERE service_id=?',[json_encode($m),$service['id']]);}
