query('UPDATE shop_resource_links SET credentials=?,metadata=? WHERE service_id=?',[secret_seal($creds,'service:'.$s['id']),json_encode($meta),$s['id']]);$api->control($node,$vmid,'start','lxc');queue_server_credentials(bound_service((int)$s['id'],(int)$s['customer_id']),'server-credentials:reinstall:'.$op['id']);query("UPDATE shop_server_operations SET state='done',phase='done',last_error=NULL WHERE id=?",[$op['id']]);customer_notification((int)$s['customer_id'],'server-reinstall:'.$op['id'],'Server neu installiert','Die neuen Zugangsdaten erhältst du per E-Mail.','/konto/verwalten?id='.$s['id']);$count++;}
    });}catch(Throwable $e){query("UPDATE shop_server_operations SET state='needs_action',last_error=? WHERE id=?",[mb_substr($e instanceof ProviderFailure?$e->getMessage():($e instanceof RuntimeException && !($e instanceof PDOException)?$e->getMessage():'Serverauftrag konnte nicht abgeschlossen werden.'),0,500),$op['id']]);}finally{query('UPDATE shop_server_operations SET locked_until=0,lock_token=NULL WHERE id=? AND lock_token=?',[$op['id'],$token]);}}
